<h2 class="h4 mb-3">取消申请</h2><div class="table-responsive table-card"><table class="table table-hover"><tr><th>ID</th><th>用户</th><th>目标</th><th>类型</th><th>方式</th><th>原因</th><th>状态</th><th>操作</th></tr><?php foreach ($list as $r): ?><tr><td><?=h($r['id'])?></td><td><?=h($r['user_id'])?></td><td><?=h($r['target_id'])?></td><td><?=h($r['type'])?></td><td><?=h($r['mode'])?></td><td><?=h($r['reason'])?></td><td><?=status_badge($r['status'], 'cancel')?></td><td><?php if ($r['status'] === 'pending'): ?><form method="post" action="<?=h(url_to('admin/cancel_request/handle'))?>" class="d-inline"><?=csrf_field()?><input type="hidden" name="id" value="<?=h($r['id'])?>"><input type="hidden" name="decision" value="approve"><button class="btn btn-sm btn-success" data-confirm="确认批准并执行取消？">批准</button></form> <form method="post" action="<?=h(url_to('admin/cancel_request/handle'))?>" class="d-inline"><?=csrf_field()?><input type="hidden" name="id" value="<?=h($r['id'])?>"><input type="hidden" name="decision" value="reject"><button class="btn btn-sm btn-outline-danger">驳回</button></form><?php endif; ?></td></tr><?php endforeach; ?></table></div><?=pager_html($total, $page, $size, isset($_GET) ? $_GET : array())?>
